import Foundation\n/// Tracks retry execution metrics.\npublic actor RetryMetrics: Sendable {\n    public private(set) var totalAttempts = 0\n    public private(set) var totalSuccesses = 0\n    public private(set) var totalFailures = 0\n    public func recordAttempt() { totalAttempts += 1 }\n    public func recordSuccess() { totalSuccesses += 1 }\n    public func recordFailure() { totalFailures += 1 }\n}
